from pathlib import Path
import json, hashlib, html
from datetime import datetime
from zoneinfo import ZoneInfo
root=Path.cwd();out=root/'output/engineering-fixture-verification'
load=lambda name:json.loads((out/name).read_text(encoding='utf-8'))
unit=load('unit-results.json');assert unit['success'] and unit['numFailedTests']==0
groups=[('Firebase/หน้าจอจริงในเครื่อง','ui-results.json'),('รุ่น build / Firebase Auth จริง','built-ui-results.json'),('หน้าจอผลและข้อมูลกรณี — records จำลอง','render-ui-results.json'),('Excel จาก implementation จริง — backend reads จำลอง','excel-render-results.json')]
for _,name in groups:
 data=load(name);assert data['results'] and all(r['status']=='PASS' for r in data['results']);assert not data.get('errors') and not data.get('cloud')
baseline=json.loads((root/'output/source-schedule-verification/config-baseline.json').read_text(encoding='utf-8'));protected={k:v for k,v in baseline.items() if k!='src/data/clientCommands.ts'}
config={}
for name,digest in protected.items():
 actual=hashlib.sha256((root/name).read_bytes()).hexdigest();assert actual==digest,name+' changed';config[name]={'before':digest,'after':actual,'unchanged':True}
config['src/data/clientCommands.ts']={'before':baseline['src/data/clientCommands.ts'],'after':hashlib.sha256((root/'src/data/clientCommands.ts').read_bytes()).hexdigest(),'intentionalChange':'Adds two lazy-dispatched fixture commands; existing issue closure and Auth/API protocol preserved.'}
(out/'config-verification.json').write_text(json.dumps(config,indent=2),encoding='utf-8')
files=['fixture-match.xlsx','fixture-missing-bar.xlsx','existing-flow-backup.zip','render-only-run.json','render-only-case.json']
artifacts=[{'name':name,'bytes':(out/name).stat().st_size,'sha256':hashlib.sha256((out/name).read_bytes()).hexdigest()} for name in files]
(out/'artifact-verification.json').write_text(json.dumps(artifacts,indent=2),encoding='utf-8')
e=html.escape
rows=''.join('<tr><td>'+e(label)+'</td><td>'+str(len(load(name)['results']))+'</td><td>'+e(load(name)['scope'] if 'scope' in load(name) else load(name)['backend'])+'</td><td><a href="'+name+'">หลักฐาน JSON</a></td></tr>' for label,name in groups)
details=''.join('<details><summary>'+e(label)+'</summary><ul>'+''.join('<li>'+e(r['name'])+' — '+r['status']+'</li>' for r in load(name)['results'])+'</ul></details>' for label,name in groups)
file_rows=''.join('<tr><td><a href="'+a['name']+'">'+a['name']+'</a></td><td>'+f"{a['bytes']:,}"+'</td><td><code>'+a['sha256']+'</code></td></tr>' for a in artifacts)
images=[('built-preparation-desktop.png','หน้าจอแอป build จริง · เปิดเตรียมข้อมูล · ยังไม่เปิดบันทึก'),('built-input-mobile-bottom.png','ฟอร์มในรุ่น build ที่390px · ตารางเลื่อนและปุ่มบันทึกปิดไว้'),('app-stale-input.png','การแก้สมาชิกจากอีกหน้าคง input/ผลอ้างอิงเดิมในฟอร์ม จนกดโหลดล่าสุด'),('render-results-mobile.png','หน้าผลตรวจจาก component จริง · records จำลองและระบุไว้ในภาพ'),('excel-comparisons.png','ไฟล์ XLSX จาก implementation จริง · backend reads จำลอง · สูตรผลต่างและสถานะ captured'),('excel-full-input-tail.png','ส่วนท้าย snapshot ใน Excel · แบ่ง JSON โดยไม่ทิ้งฟิลด์'),('excel-missing-values.png','ค่าจริงและผลต่างที่ไม่มีข้อมูลเป็นช่องว่าง ไม่แทนด้วย0')]
figures=''.join('<figure><a href="'+name+'"><img src="'+name+'" alt="'+e(label)+'"></a><figcaption>'+e(label)+'</figcaption></figure>' for name,label in images)
timestamp=datetime.now(ZoneInfo('Asia/Bangkok')).isoformat(timespec='seconds')
